/*	Build Failure Record - flattens the error trigger payload into one readable row.	*/
/*	The error payload carries workflow and execution metadata only, never the failing
	workflow's own data. The affected event id is recovered downstream by fetching the
	failed execution back through the n8n API.	*/

const cfg_obj = $('Config').first().json;
const err_obj = $('Workflow Failed').first().json || {};

const wf_obj = err_obj.workflow || {};
const ex_obj = err_obj.execution || {};
const detail_obj = ex_obj.error || err_obj.error || {};

const wfId_str = String(wf_obj.id || '');
const exId_str = String(ex_obj.id || '');

/*	Built from Config rather than from the payload, because the payload's own url field
	is absent on some failure shapes and a half-built link is worse than a whole one	*/
const url_str = (wfId_str && exId_str)
	? String(cfg_obj.N8N_BASE_URL) + '/workflow/' + wfId_str + '/executions/' + exId_str
	: '';

const node_str = String(ex_obj.lastNodeExecuted || detail_obj.node?.name || '');
const msg_str = String(detail_obj.message || err_obj.message || 'No message was carried on the error payload.');

return [{ json: {
	occurred_at: $now.toISO(),
	workflow_name: String(wf_obj.name || ''),
	workflow_id: wfId_str,
	execution_id: exId_str,
	execution_url: url_str,
	failed_node: node_str,
	error_message: msg_str
} }];

/*	Recover Event Id - digs the affected event out of the fetched execution.	*/
/*	Node names are deliberately not hardcoded. This handler is shared across four
	workflows that carry the event id under different node names, so every node's output
	is scanned for the keys listed in Config and the first non-empty match wins.	*/

const cfg_obj = $('Config').first().json;
const base_obj = $('Build Failure Record').first().json;
const exec_obj = $input.first().json || {};

const keys_ary = String(cfg_obj.EVENT_ID_KEYS || '').split(',').map(function (k_str) { return k_str.trim(); }).filter(function (k_str) { return k_str.length > 0; });

/*	An absent data key means the fetch itself did not work, which is a different problem
	from an execution that genuinely carried no event id. The row says which	*/
const fetched_bln = !!exec_obj.data;
const runData_obj = ((exec_obj.data || {}).resultData || {}).runData || {};

let found_str = '';

for (const node_str of Object.keys(runData_obj))
{
	if (found_str) { break; }
	for (const run_obj of (runData_obj[node_str] || []))
	{
		if (found_str) { break; }
		for (const branch_ary of (((run_obj || {}).data || {}).main || []))
		{
			if (found_str) { break; }
			for (const item_obj of (branch_ary || []))
			{
				const json_obj = (item_obj || {}).json || {};
				for (const key_str of keys_ary)
				{
					const v_str = String(json_obj[key_str] === null || json_obj[key_str] === undefined ? '' : json_obj[key_str]).trim();
					if (v_str) { found_str = v_str; break; }
				}
				if (found_str) { break; }
			}
		}
	}
}

/*	attempted rather than yes, because the row is written before the Administrate call
	runs. Writing it after would mean a failure there loses the whole record, and a
	durable record of every failure matters more than a perfectly accurate flag	*/
const state_str = !fetched_bln
	? 'no - could not fetch the failed execution, check the n8n API credential'
	: (found_str ? 'attempted' : 'no - the failed execution carried no event id');

return [{ json: Object.assign({}, base_obj, { event_id: found_str, logged_to_administrate: state_str }) }];

